"Die halbe Schwingungsbreite einer periodischen Funktion. Gibt an, wie weit der Graph maximal vom Mittelwert (Mittellinie) abweicht.": "Egy periodikus függvény lengésszélességének fele. Megadja, hogy a grafikon legfeljebb mennyire tér el az átlagértéktől (középvonaltól).",
"Die kleinste positive Zahl T, nach der sich der Funktionswert wiederholt: {0} = {1}. Für sin und cos: T = {2}π/b. Für tan: T = π/b.": "A legkisebb pozitív T szám, amely után a függvényérték megismétlődik: {0} = {1}. sin és cos esetén: T = {2}π/b. tan esetén: T = π/b.",
"Die momentane Änderungsrate von f an der Stelle x. Geometrisch ist sie die Steigung der Tangente an den Graphen in (x | {0}). Wichtige Regeln: Potenzregel (xⁿ)'=n·xⁿ⁻¹, Summenregel, Produktregel, Kettenregel.": "Az f függvény pillanatnyi változási sebessége az x helyen. Geometriailag a grafikon (x | {0}) pontjához húzott érintő meredeksége. Fontos szabályok: hatványszabály (xⁿ)'=n·xⁿ⁻¹, összegszabály, szorzatszabály, láncszabály.",
