"Ein Graph ist auf einem Intervall konkav (nach unten offen, «Kuppel»), wenn die zweite Ableitung dort negativ ist. Jede Sekante liegt unter dem Graphen.": "Egy grafikon egy intervallumon konkáv (lefelé nyitott, „kupola”), ha a második derivált ott negatív. Minden szelő a grafikon alatt halad.",
