"Eine Exponentialfunktion mit positiver Basis ist stets positiv — {0} hat <1>keine Lösung</1>.": "Pozitív alapú exponenciális függvény mindig pozitív — erre: {0} <1>nincs megoldás</1>.",
"Eine Funktion F, deren Ableitung die Ausgangsfunktion f ergibt. Ist nicht eindeutig: {0} + C ist ebenfalls eine Stammfunktion (C: Integrationskonstante). Grundregel: ∫xⁿdx = xⁿ⁺¹/(n+{1}) + C": "Olyan F függvény, amelynek deriváltja az eredeti f függvény. Nem egyértelmű: {0} + C is primitív függvény (C: integrációs konstans). Alapszabály: ∫xⁿdx = xⁿ⁺¹/(n+{1}) + C",
"Eine Funktion f ordnet jedem Element x der Definitionsmenge D genau ein Element {0} der Wertemenge W zu. Kein x-Wert darf zwei verschiedene y-Werte haben.": "Az f függvény a D értelmezési tartomány minden x eleméhez pontosan egy {0} elemet rendel a W értékkészletből. Egyetlen x értéknek sem lehet két különböző y értéke.",
"Eine Funktion ist auf einem Intervall I monoton fallend, wenn grössere x-Werte kleinere (oder gleich grosse) Funktionswerte liefern. Bei streng monoton fallend gilt striktes {0}.": "Egy függvény az I intervallumon monoton csökkenő, ha nagyobb x-értékekhez kisebb (vagy egyenlő) függvényértékek tartoznak. Szigorúan monoton csökkenő esetén szigorú egyenlőtlenség ({0}) érvényes.",
"Eine Funktion ist auf einem Intervall I monoton steigend, wenn grössere x-Werte auch grössere (oder gleich grosse) Funktionswerte liefern. Bei streng monoton steigend gilt striktes {0}.": "Egy függvény az I intervallumon monoton növekvő, ha nagyobb x értékekhez nagyobb (vagy egyenlő) függvényértékek tartoznak. Szigorúan monoton növekvő esetén szigorú {0} érvényes.",
"Eine Funktion ist stetig in a, wenn der Grenzwert existiert und gleich dem Funktionswert {0} ist — keine Sprünge, Lücken oder Pole. Polynomfunktionen sind überall stetig.": "Egy függvény az a helyen folytonos, ha a határérték létezik, és egyenlő a függvényértékkel: {0} — nincsenek ugrások, szakadások vagy pólusok. A polinomfüggvények mindenütt folytonosak.",
