"Fläche ausblenden": "Terület elrejtése",
"Fläche konnte nicht berechnet werden — f ist im Intervall evtl. nicht (umkehrbar) definiert.": "A terület nem számítható ki — f az intervallumban esetleg nincs (invertálhatóan) értelmezve.",
"Fläche zwischen Funktionen": "Terület Függvények Között",
"Fläche zwischen f und der y-Achse im Intervall [{0}, {1}] (y-Werte)": "f és az y-tengely közötti terület az [{0}, {1}] intervallumban (y-értékek)",
"Fläche zwischen f und {0} im Intervall [{1}, {2}]": "f és {0} közötti terület az [{1}, {2}] intervallumban",
"Fläche zwischen zwei Funktionsgraphen. Man zieht die untere Funktion von der oberen ab und integriert. Vorzeichen beachten — bei Vorzeichenwechsel der Differenz aufteilen.": "Két függvénygrafikon közötti terület. Az alsó függvényt kivonjuk a felsőből, és integrálunk. Figyelj az előjelre — ha a különbség előjelet vált, bontsd részekre.",
"Fläche zwischen {0}=x² und {1}=x: A = ∫[{2}] (x−x²)dx = {3}/{4}": "Terület {0}=x² és {1}=x között: A = ∫[{2}] (x−x²)dx = {3}/{4}",
"Fläche ≈ {0}": "Terület ≈ {0}",
"Fläche ≈ {0} <1>(numerische Näherung)</1>": "Terület ≈ {0} <1>(numerikus közelítés)</1>",
"Flächeninhalt zwischen Graphen": "Grafikonok közötti terület",
"Form aufschalten, dann a, b, c bzw. a, v, h oben mit den Schiebereglern verändern.": "Kapcsolj be egy alakot, majd módosítsd a, b, c-t (vagy a, v, h-t) a fenti csúszkákkal.",
"Form aufschalten, dann a, b, c und d oben mit den Schiebereglern verändern (a = Amplitude, b = Frequenz, c = Phasenverschiebung, d = Verschiebung nach oben/unten).": "Kapcsold be a formát, majd fent állítsd a, b, c és d értékét a csúszkákkal (a = amplitúdó, b = frekvencia, c = fáziseltolás, d = eltolás fel/le).",
"Formen (Schieberegler)": "Alakok (csúszkák)",
"Freie Punkte": "Szabad pontok",
"Funktion": "Függvény",
"Funktion eingeben und aufschalten: Punkt A und Punkt B sind beide ziehbar. Ziehe A und B nahe zusammen — der Differenzenquotient nähert sich dann dem Differentialquotienten (der Ableitung) an.": "Adj meg egy függvényt és aktiváld: az A pont és a B pont is húzható. Húzd A-t és B-t közel egymáshoz — a differenciahányados így közelít a differenciálhányadoshoz (a derivált).",
"Funktion eingeben und aufschalten: die Intervallgrenzen a und b sind ziehbar. Ober-/Untersumme zwischen f und der x-Achse — erhöhe n, um dich dem exakten Integral anzunähern.": "Add meg a függvényt és aktiváld: az a és b intervallumhatárok húzhatók. Felső/alsó összeg f és az x-tengely között — növeld n-t a pontos integrálhoz közelítéshez.",
"Funktion eingeben, Randart wählen und aufschalten: die Intervallgrenzen a und b sind ziehbar (und frei eintippbar).": "Add meg a függvényt, válaszd ki a határ típusát és aktiváld: az a és b intervallumhatárok húzhatók (és szabadon beírhatók).",
"Funktion, bei der die Variable im Exponenten steht. Für b {0} {1}: exponentielles Wachstum. Für {2} {3} b {4} {5}: exponentieller Zerfall. Immer positiv, keine Nullstelle. Definitionsbereich: ℝ.": "Olyan függvény, amelyben a változó a kitevőben áll. b {0} {1} esetén: exponenciális növekedés. {2} {3} b {4} {5} esetén: exponenciális csökkenés. Mindig pozitív, nincs zérushelye. Értelmezési tartomány: ℝ.",
"Funktionenplotter": "Függvényplotter",
"Funktionsbeschriftung im Plot": "Függvény feliratok a ploton",
"Funktionstyp: {0} = {1}·{2}ˣ": "Függvénytípus: {0} = {1}·{2}ˣ",
"Fülle mindestens {0} der {1} Felder aus — das leere Feld wird automatisch berechnet.": "Tölts ki legalább {0} mezőt a(z) {1} közül — az üres mező automatikusan kiszámolódik.",
"Für die Senkrechte: Punkt und Gerade im Plot wählen. Für die Mittelsenkrechte: zwei Punkte wählen. Inkl. Lösungsweg und Beziehung der Steigungen (m₁·m₂ = −{0}).": "A merőlegeshez: válassz pontot és egyenest a grafikonon. A felezőmerőlegeshez: válassz két pontot. Megoldási lépésekkel és a meredekségek közti összefüggéssel (m₁·m₂ = −{0}).",
"Für diese Funktion konnte keine elementare Stammfunktion gefunden werden.": "Ehhez a függvényhez nem található elemi primitív függvény.",
"Für n gerade: achsensymmetrisch, Definitionsbereich ℝ. Für n ungerade: punktsymmetrisch, Definitionsbereich ℝ. Für n {0} {1}: Pol bei x = {2}, hyperbelartig.": "Páros n esetén: tengelyszimmetrikus, értelmezési tartomány ℝ. Páratlan n esetén: középpontosan szimmetrikus, értelmezési tartomány ℝ. n {0} {1} esetén: pólus az x = {2} helyen, hiperbolaszerű.",
"Für x → {0}: Zähler bleibt konstant ({1}), Nenner wächst über alle Grenzen (Wurzelterm dominiert)": "x → {0} esetén: a számláló konstans marad ({1}), a nevező minden határon túl nő (a gyökös tag dominál)",
"Für x → {0}: Zähler und Nenner wachsen beide linear in x — das Verhältnis der Leitkoeffizienten ergibt den Grenzwert:": "x → {0} esetén: a számláló és a nevező is lineárisan nő x-ben — a főegyütthatók hányadosa adja a határértéket:",
"Für x → ±∞: {0}/({1}) → {2}": "x → ±∞ esetén: {0}/({1}) → {2}",
"Für {0} strebt der Summand {1} gegen {2} (Exponentialfunktion mit abnehmendem Exponenten). Es bleibt der Rest:": "Ha {0}, a tag ({1}) határértéke {2} (csökkenő kitevőjű exponenciális függvény). Marad a maradék:",
"Gebrochen-rationale Funktion": "Törtfüggvény (racionális törtfüggvény)",
"Gekürzt (für x ≠ {0}): {1} = [{2}] / [{3}]": "Egyszerűsítve (x ≠ {0} esetén): {1} = [{2}] / [{3}]",
"Gekürzte Funktion": "Egyszerűsített függvény",
"Gemeinsamer Punkt zweier Graphen. Berechnung durch Gleichsetzen: {0} = {1} nach x auflösen, dann y = {2} berechnen.": "Két grafikon közös pontja. Kiszámítása egyenlővé tétellel: oldd meg x-re a {0} = {1} egyenletet, majd számítsd ki y = {2} értékét.",
"Geometrische Darstellung der Steigung am Graphen: Man wählt zwei Punkte, zieht eine waagrechte Strecke (Δx) und eine senkrechte Strecke (Δy). Die Steigung ist m = Δy/Δx.": "A meredekség geometriai ábrázolása a grafikonon: kiválasztunk két pontot, húzunk egy vízszintes (Δx) és egy függőleges (Δy) szakaszt. A meredekség m = Δy/Δx.",
"Gerade aufschalten, dann m und q oben mit den Schiebereglern verändern.": "Kapcsold be, majd módosítsd m-et és q-t a fenti csúszkákkal.",
"Gerade, die den Graphen im Punkt (x₀ | {0}) berührt. Die Steigung der Tangente ist gleich {1}. Die Tangente ist die beste lineare Näherung des Graphen an dieser Stelle.": "Egyenes, amely az (x₀ | {0}) pontban érinti a grafikont. Az érintő meredeksége egyenlő a következővel: {1}. Az érintő a grafikon legjobb lineáris közelítése ezen a helyen.",
"Gerade, die den Graphen in zwei Punkten schneidet. Die Steigung der Sekante entspricht dem Differenzenquotienten — der durchschnittlichen Änderungsrate.": "Egyenes, amely a grafikont két pontban metszi. A szelő meredeksége a differenciahányadosnak — az átlagos változási sebességnek — felel meg.",
"Geradengleichung": "Az egyenes egyenlete",
"Geradengleichung:": "Az egyenes egyenlete:",
