"Stelle, an der {0}={1} und {2}={3}, aber kein Vorzeichenwechsel von f' vorliegt. Der Graph «zögert» kurz, steigt oder fällt aber weiter in dieselbe Richtung.": "Olyan hely, ahol {0}={1} és {2}={3}, de f' nem vált előjelet. A grafikon rövid időre „megtorpan”, de ugyanabba az irányba emelkedik vagy süllyed tovább.",
