"<0>Keine reelle Nullstelle</0> — die Parabel schneidet die {1}-Achse nicht.": "<0>Nincs valós zérushely</0> — a parabola nem metszi az {1}-tengelyt.",
"Achtung: {0} — das Vorzeichen in der Klammer ist umgekehrt.": "Figyelem: {0} — a zárójelben lévő előjel fordított.",
"Doppelte Nullstelle: {0}": "Kétszeres zérushely: {0}",
"Die Funktion steht in <0>Nullstellenform</0> {1}. Die Parabel ist symmetrisch — der Scheitelpunkt liegt genau in der Mitte zwischen den Nullstellen:": "A függvény <0>gyökalakban</0> van megadva {1}. A parabola szimmetrikus — a csúcspont pontosan a zérushelyek között félúton van:",
"{0} erhält man, indem man {1} in die Funktion einsetzt:": "{0}-t úgy kapjuk, hogy {1}-et behelyettesítjük a függvénybe:",
"<0>Scheitelpunktform</0>:": "<0>Csúcsalak</0>:",
"Die Funktion steht in <0>Nullstellenform</0>. Setze {1}:": "A függvény <0>gyökalakban</0> van megadva. Legyen {1}:",
"Die Funktion steht in <0>Normalform</0> {1} mit {2}. Die Scheitelstelle ist:": "A függvény <0>általános alakban</0> van megadva {1}, ahol {2}. A csúcspont x-koordinátája:",
"Aus der Geradengleichung {0} lassen sich Steigung und y-Achsenabschnitt direkt ablesen:": "Az egyenes {0} egyenletéből közvetlenül leolvasható a meredekség és az y-tengelymetszet:",
"Die Gerade schneidet die y-Achse im Punkt {0}.": "Az egyenes az y-tengelyt a {0} pontban metszi.",
"<0>Nullstelle</0> ({1} setzen):": "<0>Zérushely</0> ({1} beállítása):",
"Die Gerade ist die {0}-Achse selbst — jede Stelle ist eine Nullstelle.": "Az egyenes maga az {0}-tengely — minden pont zérushely.",
"<0>Nullstelle</0>: Die Gerade ist waagrecht ({1}) und verläuft parallel zur {2}-Achse — <3>keine Nullstelle</3>.": "<0>Zérushely</0>: az egyenes vízszintes ({1}), és párhuzamos az {2}-tengellyel — <3>nincs zérushely</3>.",
"{0}: Gerade durch {1} und {2}": "{0}: egyenes a {1} és {2} ponton át",
"<0>Steigung</0> aus den beiden Punkten:": "<0>Meredekség</0> a két pontból:",
"<0>y-Achsenabschnitt</0> {1}: den Punkt {2} in {3} einsetzen:": "<0>y-tengelymetszet</0> {1}: helyettesítsd be a(z) {2} pontot a(z) {3} egyenletbe:",
"Geradengleichung: {0}": "Az egyenes egyenlete: {0}",
