"Hier nur Gleichungen, in denen die Variable einmal vorkommt (linear in Hochzahl bzw. Argument)": "Itt csak olyan egyenletek, amelyekben a változó egyszer szerepel (lineárisan a kitevőben vagy az argumentumban)",
"Das Produkt von Logarithmen wird hier nicht umgeformt": "Logaritmusok szorzatát itt nem alakítjuk át",
"Durch Logarithmen wird hier nicht geteilt": "Itt nem osztunk logaritmussal",
"Bei ln lässt sich eine Zahl nur als e^k schreiben – bitte zuerst k als ln(e^k) schreiben": "ln esetén egy szám csak e^k alakban írható – előbb írd fel k-t ln(e^k) alakban",
