"Ein Produkt ist eine Fläche: Jede Klammer ist eine Seite des Rechtecks, die Teilrechtecke sind die Teilprodukte.": "A szorzat egy terület: minden zárójel a téglalap egy oldala, a részterületek a részszorzatok.",
