"Die Formel bleibt dieselbe: a = {0}x und b = {1}y. Darum {2}x² − {3}xy + {4}y².": "A képlet ugyanaz marad: a = {0}x és b = {1}y. Ezért {2}x² − {3}xy + {4}y².",
"Das Quadrat mit der Seite a + b besteht aus dem Quadrat a², dem Quadrat b² und zwei Rechtecken ab.": "Az a + b oldalú négyzet az a² négyzetből, a b² négyzetből és két ab téglalapból áll.",
"Vom Quadrat a² werden zwei Streifen ab abgezogen. Das Eckquadrat b² wurde dabei zweimal weggenommen und kommt einmal zurück.": "Az a² négyzetből két ab csíkot levonunk. A b² saroknégyzetet így kétszer vettük el, és egyszer visszakapjuk.",
"Ein Streifen wird umgelegt: Übrig bleibt a² − b², ein Rechteck mit den Seiten a + b und a − b.": "Egy csíkot átfordítunk: marad a² − b², egy a + b és a − b oldalú téglalap.",
"Jede Kachel ist eine Fläche: ein x², fünf x und sechs {0}.": "Minden csempe egy terület: egy x², öt x és hat {0}.",
"Negative Teilflächen werden abgezogen. Rot sind die negativen Kacheln.": "A negatív részterületeket levonjuk. A negatív csempék pirosak.",
"Der Würfel mit der Kante a + b besteht aus a³, b³, drei Quadern a²b und drei Quadern ab².": "Az a + b élű kocka a³-ből, b³-ből, három a²b hasábból és három ab² hasábból áll.",
"Tippe auf «Beispiel», dann wird es vorgerechnet und gezeichnet.": "Koppints a „Példa” gombra, akkor kiszámítjuk és lerajzoljuk.",
