"Das Quadrat x² mit zwei Rechtecken {0}x lässt eine Ecke {1}² = {2} offen. Man ergänzt sie und zieht sie wieder ab.": "Az x² négyzet két {0}x téglalappal egy {1}² = {2} sarkot hagy üresen. Kiegészítjük, majd újra levonjuk.",
"Die Hälfte von −{0} ist −{1}; das Quadrat ergänzen: (x − {2})² − {3}.": "−{0} fele −{1}; a négyzet kiegészítése: (x − {2})² − {3}.",
"Zuerst die {0} ausklammern, dann ergänzen: {1}(x − {2})² − {3}. Der Scheitelpunkt ist {4}.": "Először kiemeljük ({0}), majd kiegészítünk: {1}(x − {2})² − {3}. A csúcspont: {4}.",
"Schreibe mit vollständigem Quadrat:": "Írd fel teljes négyzettel:",
"Die Zeilen des Pascal'schen Dreiecks sind die Koeffizienten von (a + b)ⁿ.": "A Pascal-háromszög sorai az (a + b)ⁿ együtthatói.",
