"Die Zeile {0} des Pascal'schen Dreiecks: {1}.": "A Pascal-háromszög {0}. sora: {1}.",
"a = {0}x und b = −{1}: Jedes Glied hat einen Koeffizienten aus Zeile {2} mal die Potenzen von {3} und −{4}.": "a = {0}x és b = −{1}: minden tagnak van egy együtthatója a Pascal-háromszögből (sor: {2}), szorozva {3} és −{4} hatványaival.",
"Auch für grosse Hochzahlen: Die Binomialkoeffizienten stehen in Zeile {0}.": "Nagy kitevőknél is: a binomiális együtthatók a Pascal-háromszög {0}. sorában vannak.",
"Pascal'sches Dreieck": "Pascal-háromszög",
"Jede Hochzahl ist eine Reihe von Bausteinen: Beim Multiplizieren werden Reihen aneinandergelegt, beim Dividieren Bausteine weggekürzt.": "Minden kitevő építőelemek sora: szorzáskor a sorokat egymás mellé tesszük, osztáskor az építőelemeket egyszerűsítjük.",
