"<0>Alles zusammen</0>{1}": "<0>Mindez együtt</0>{1}",
"Gleiche Basis: Die Reihen werden aneinandergelegt, die Hochzahlen addieren sich.": "Azonos alap: a sorokat egymás mellé tesszük, a kitevők összeadódnak.",
"Gleiche Bausteine oben und unten werden gekürzt: Die Hochzahlen werden subtrahiert.": "A számlálóban és a nevezőben azonos építőelemek egyszerűsödnek: a kitevőket kivonjuk.",
"Drei Reihen mit je zwei Bausteinen: Die Hochzahlen werden multipliziert.": "Három sor, mindegyikben két építőelem: a kitevőket összeszorozzuk.",
"Dreimal das Paar a·b: Man erhält a³ und b³, die Hochzahl gilt für jeden Faktor.": "Háromszor az a·b pár: a³-t és b³-t kapunk, a kitevő minden tényezőre vonatkozik.",
"Dreimal der Bruch a/b: oben a³, unten b³.": "Háromszor az a/b tört: felül a³, alul b³.",
"Eine negative Hochzahl bedeutet den Kehrwert: Die Bausteine wandern in den Nenner.": "A negatív kitevő a reciprokot jelenti: az építőelemek a nevezőbe vándorolnak.",
"Dieselbe Regel gilt für Zahlen: {0}³ · {1}⁴ = {2}⁷ = {3}.": "Ugyanez a szabály számokra is igaz: {0}³ · {1}⁴ = {2}⁷ = {3}.",
"Erst auf gleiche Basis bringen: {0} = {1}², dann ist es {2}⁴ · {3}³ = {4}⁷.": "Először azonos alapra hozzuk: {0} = {1}², akkor {2}⁴ · {3}³ = {4}⁷.",
"Zuerst Klammern auflösen, dann gleiche Basen zusammenfassen: a⁶b³ / (ab²) = a⁵b.": "Először a zárójeleket bontjuk fel, majd az azonos alapokat vonjuk össze: a⁶b³ / (ab²) = a⁵b.",
