"{0} = {1}² · {2}: Aus dem Quadrat {3}² kann man {4} vor die Wurzel ziehen. Es bleibt {5}√{6}.": "{0} = {1}² · {2}: A négyzetszám ({3}²) gyöke, {4}, a gyökjel elé kerül. Marad {5}√{6}.",
"Die Hochzahl {0}/{1} sind drei halbe Bausteine: ein ganzer Baustein x und ein halber, also x·√x.": "Kitevő: {0}/{1}, vagyis három fél építőelem: egy egész x építőelem és egy fél, tehát x·√x.",
"Zwei halbe Bausteine ergeben einen ganzen: √x · √x = x.": "Két fél építőelem egy egészet ad: √x · √x = x.",
