"{0} = {1}³, also ist {2}^({3}/{4}) = {5}² = {6}. Die Hochzahl {7}/{8} bedeutet «dritte Wurzel, dann quadrieren».": "{0} = {1}³, tehát {2}^({3}/{4}) = {5}² = {6}. A kitevő ({7}/{8}) jelentése: „köbgyök, majd négyzetre emelés”.",
