"{0} liegt zwischen {1}² = {2} und {3}³ = {4}: Der Logarithmus liegt zwischen {5} und {6} (≈ {7}).": "{0} {1}² = {2} és {3}³ = {4} között van: a logaritmus {5} és {6} között van (≈ {7}).",
