"Der Punkt P liegt fest auf dem Graphen, der Punkt Q wandert. Die Sekante durch P und Q hat die Steigung ms = Δy / h.": "A P pont rögzített a grafikonon, a Q pont mozog. A P-n és Q-n átmenő szelő meredeksége ms = Δy / h.",
