"{0} x wandert nach rechts": "{0} x jobbra mozog",
"{0} <1>Fläche von a bis x färben</1>": "{0} <1>Terület színezése a-tól x-ig</1>",
"{0} <1>Tangente an Fa zeigen (Steigung {2})</1>": "{0} <1>Fa érintőjének mutatása (meredekség {2})</1>",
"Rechenweg: Integralfunktion": "Számítás: integrálfüggvény",
"Die <0>Integralfunktion</0> sammelt die Fläche zwischen {1} und der {2}-Achse ab der festen Stelle {3}. Oberhalb der Achse wächst sie, unterhalb nimmt sie ab.": "Az <0>integrálfüggvény</0> összegyűjti a {1} és az {2}-tengely közötti területet a rögzített {3} helytől. A tengely felett nő, alatta csökken.",
"<0>Schritt {1}:</0> Eine Stammfunktion {2} von {3} bestimmen.": "<0>{1}. lépés:</0> Primitív függvény meghatározása: {2} a(z) {3} függvényhez.",
"<0>Schritt {1}:</0> Hauptsatz der Differential- und Integralrechnung.": "<0>{1}. lépés:</0> A differenciál- és integrálszámítás alaptétele.",
"<0>Schritt {1}:</0> Ableiten der Integralfunktion gibt die Funktion zurück:": "<0>{1}. lépés:</0> Az integrálfüggvény deriválása visszaadja a függvényt:",
"Die Steigung von {0} an der Stelle {1} ist {2}.": "{0} meredeksége az {1} helyen {2}.",
"Für diese Funktion gibt es keine Stammfunktion in einfacher Form; die Integralfunktion wird numerisch berechnet.": "Ennek a függvénynek nincs egyszerű alakú primitív függvénye; az integrálfüggvényt numerikusan számoljuk.",
"Die Stammfunktion wird Schritt für Schritt mit den Integrationsregeln bestimmt. Danach folgt das bestimmte Integral zwischen a und b.": "A primitív függvényt lépésről lépésre az integrálási szabályokkal határozzuk meg. Utána jön a határozott integrál a és b között.",
"Ziehe a und b auf der x-Achse. Die Stammfunktion ist nur bis auf eine Konstante C bestimmt: Alle Stammfunktionen sind gegeneinander verschoben.": "Húzd az a és b pontot az x-tengelyen. A primitív függvény csak egy C konstans erejéig meghatározott: az összes primitív függvény egymás eltoltja.",
"{0} <1>Fläche von a bis b färben</1>": "{0} <1>Terület színezése a-tól b-ig</1>",
"{0} <1>Stammfunktion F einzeichnen</1>": "{0} <1>F primitív függvény berajzolása</1>",
"{0} <1>Schar F + C zeigen (andere Konstanten)</1>": "{0} <1>F + C sereg mutatása (más konstansok)</1>",
