"<0>Schritt {1}:</0> Nullstellen von {2} im Intervall suchen ({3}).": "<0>{1}. lépés:</0> {2} zérushelyeinek keresése az ({3}) intervallumban.",
"Im Inneren des Intervalls gibt es keine Nullstelle, also wechselt das Vorzeichen nicht.": "Az intervallum belsejében nincs zérushely, tehát az előjel nem változik.",
"<0>Schritt {1}:</0> Das Intervall an diesen Stellen teilen und jedes Stück einzeln integrieren. Unterhalb der Achse (bzw. von {2}) ist das Integral negativ, die Fläche ist sein Betrag.": "<0>{1}. lépés:</0> Az intervallum felosztása ezeken a helyeken, és minden darab külön integrálása. A tengely (ill. {2}) alatt az integrál negatív, a terület az abszolút értéke.",
