"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst (Steigungsdreieck), q ist der y-Achsenabschnitt.": "Lineáris függvény: {0} = m·x + q, grafikonja egyenes. Az m meredekség azt adja meg, mennyivel nő y, ha {1} egységgel jobbra lépünk (meredekségi háromszög), q az y-tengelymetszet.",
"Ziehe den violetten Punkt S, um q zu ändern, oder verändere m mit dem Regler. Die Wertetabelle zeigt, dass y bei jedem Schritt um m wächst.": "Húzd az S lila pontot q megváltoztatásához, vagy változtasd m-et a csúszkával. Az értéktáblázat mutatja, hogy y minden lépésnél m-mel nő.",
