"Das ist keine lineare Funktion. Erlaubt ist m·x + q.": "Ez nem lineáris függvény. Megengedett alak: m·x + q.",
"Eine Gerade ist durch zwei Punkte oder durch einen Punkt und die Steigung festgelegt. Aus Δy und Δx folgt m, dann folgt q aus einem Punkt.": "Egy egyenest két pont, vagy egy pont és a meredekség határoz meg. Δy-ból és Δx-ből adódik m, majd q egy pontból.",
