"Potenzfunktionen {0} = xⁿ mit natürlichem n. Für gerades n ist der Graph achsensymmetrisch zur y-Achse, für ungerades n punktsymmetrisch zum Ursprung. Alle gehen durch ({1}|{2}) und ({3}|{4}).": "Az {0} = xⁿ hatványfüggvények természetes n kitevővel. Páros n esetén a grafikon tengelyesen szimmetrikus az y-tengelyre, páratlan n esetén középpontosan szimmetrikus az origóra. Mindegyik átmegy az ({1}|{2}) és ({3}|{4}) ponton.",
