"<0>Vergleich mit kleineren Exponenten:</0> Für {1} wird {2} mit wachsendem {3} kleiner, für {4} grösser. Darum liegen die Graphen zwischen {5} und {6} unter der Normalparabel und ausserhalb darüber. Je grösser {7}, desto flacher nahe {8} und desto steiler aussen.": "<0>Összehasonlítás kisebb kitevőkkel:</0> {1} esetén {2} a növekvő {3} mellett kisebb, {4} esetén nagyobb. Ezért a grafikonok {5} és {6} között a normálparabola alatt, azon kívül felette haladnak. Minél nagyobb {7}, annál laposabb {8} közelében, és annál meredekebb kívül.",
