"Die Wurzelfunktion ⁿ√x ist die Umkehrfunktion von xⁿ: Ihr Graph ist das Spiegelbild an der Winkelhalbierenden y = x. In Potenzschreibweise ist ⁿ√x = x^({0}/n), allgemein x^(m/n) = ⁿ√(xᵐ).": "Az ⁿ√x gyökfüggvény az xⁿ inverz függvénye: a grafikonja az y = x szögfelezőre vett tükörképe. Hatvány alakban ⁿ√x = x^({0}/n), általánosan x^(m/n) = ⁿ√(xᵐ).",
