"Ähnlichkeitsabbildungen (Spiegeln, Drehen, Strecken, Verschieben), ähnliche Dreiecke, Seitenverhältnisse, Strahlensätze, rechtwinkliges Dreieck mit Höhe": "Hasonlósági transzformációk (tükrözés, forgatás, középpontos hasonlóság, eltolás), hasonló háromszögek, oldalarányok, párhuzamos szelők tétele, derékszögű háromszög magassággal",
"Datenanalyse (Mittelwert, Median, Quartile, Standardabweichung, Boxplot, Histogramm), Baumdiagramm und Pfadregeln, Binomialverteilung, Poissonverteilung, Erwartungswert und faire Spiele, Normalverteilung, Grenzwerte (Binomial → Poisson, Normal) mit Herleitung, Hypothesentest": "Adatelemzés (átlag, medián, kvartilisek, szórás, dobozdiagram, hisztogram), fadiagram és útszabályok, binomiális eloszlás, Poisson-eloszlás, várható érték és igazságos játékok, normális eloszlás, határértékek (binomiális → Poisson, normális) levezetéssel, hipotézisvizsgálat",
"Beliebige Funktionen zeichnen und untersuchen: Nullstellen, Extrema, Ableitung, Stammfunktion, Parameter mit Schiebern, Balken über den Stellen, Punkte setzen": "Tetszőleges függvények ábrázolása és vizsgálata: zérushelyek, szélsőértékek, derivált, primitív függvény, paraméterek csúszkákkal, oszlopok az x-értékek fölött, pontok elhelyezése",
