"<0>Drei Dreiecke in einem:</0> Die Höhe {1} teilt das rechtwinklige Dreieck {2} in zwei Teildreiecke. Alle drei haben die Winkel {3}, {4} und {5}, also gilt": "<0>Három háromszög egyben:</0> a {1} magasság a {2} derékszögű háromszöget két kisebb háromszögre bontja. Mindhárom szögei {3}, {4} és {5}, ezért",
