"Zwischen f und der x-Achse liegen von a bis b n gleich breite Rechtecke. Die Untersumme (grün) nimmt den kleinsten, die Obersumme (blau) den grössten Funktionswert jedes Streifens.": "Az f és az x-tengely között a-tól b-ig n egyenlő szélességű téglalap van. Az alsó összeg (zöld) minden sávban a legkisebb, a felső összeg (kék) a legnagyobb függvényértéket veszi.",
"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst, q ist der y-Achsenabschnitt.": "Az {0} = m·x + q lineáris függvény grafikonja egyenes. Az m meredekség megmutatja, mennyivel nő y, ha {1} egységet lépünk jobbra; q a tengelymetszet az y-tengelyen.",
