"Ein Hypothesentest prüft eine Annahme H₀ über eine Wahrscheinlichkeit p. Unter H₀ ist die Trefferzahl binomialverteilt. Der Ablehnungsbereich enthält die Werte, die unter H₀ zusammen höchstens die Wahrscheinlichkeit α (Signifikanzniveau) haben. Fehler {0}. Art: H₀ wird verworfen, obwohl sie stimmt.": "A hipotézisvizsgálat egy p valószínűségre vonatkozó H₀ feltevést ellenőriz. H₀ fennállása esetén a találatok száma binomiális eloszlású. Az elutasítási tartomány azokat az értékeket tartalmazza, amelyek valószínűsége H₀ mellett együtt legfeljebb α (szignifikanciaszint). {0}. fajú hiba: H₀-t elvetjük, pedig igaz.",
"Poissonverteilung: Grenzfall der Binomialverteilung für n → ∞ und p → {0} bei festem Mittelwert λ = n·p. Normalverteilung: Für grosses n rücken die Säulen der Binomialverteilung, in Einheiten von σ gemessen, immer dichter zusammen und bilden die Glockenkurve; die Zufallsgrösse wird stetig (Satz von de Moivre und Laplace).": "Poisson-eloszlás: a binomiális eloszlás határesete, ha n → ∞ és p → {0}, miközben a λ = n·p átlag rögzített. Normális eloszlás: nagy n esetén a binomiális eloszlás oszlopai σ egységekben mérve egyre sűrűbben állnak, és kirajzolják a haranggörbét; a valószínűségi változó folytonossá válik (Moivre–Laplace-tétel).",
"Viele Messgrössen (Körpergrösse, Messfehler, Abfüllmengen) sind annähernd normalverteilt. Wahrscheinlichkeiten sind Flächen unter der Glockenkurve; sie hängen nur davon ab, wie viele Standardabweichungen σ die Grenze vom Mittelwert μ entfernt ist: z = (x − μ)/σ. Beidseitig: μ ± {0}σ enthält {1} %, μ ± {2}σ {3} %, μ ± {4}σ {5} %. Umgekehrt gehören zu {6} %, {7} % und {8} % die Grenzen {9}σ, {10}σ und {11}σ.": "Sok mért mennyiség (testmagasság, mérési hiba, töltési mennyiség) közelítőleg normális eloszlású. A valószínűségek a haranggörbe alatti területek; csak attól függnek, hány σ szórásnyira van a határ a μ átlagtól: z = (x − μ)/σ. Kétoldali: μ ± {0}σ az esetek {1} %-át, μ ± {2}σ a {3} %-át, μ ± {4}σ a {5} %-át tartalmazza. Megfordítva: {6} %-hoz, {7} %-hoz és {8} %-hoz a {9}σ, {10}σ és {11}σ határ tartozik.",
"Eine Zufallsgrösse ordnet jedem Ergebnis eine Zahl zu (z. B. eine Auszahlung). Erwartungswert {0} = Σ xᵢ·{1}: der Mittelwert auf lange Sicht. Ein Spiel ist fair, wenn der Einsatz gleich dem Erwartungswert der Auszahlung ist.": "A valószínűségi változó minden kimenetelhez egy számot rendel (pl. egy kifizetést). Várható érték: {0} = Σ xᵢ·{1}, vagyis a hosszú távú átlag. Egy játék akkor igazságos, ha a tét megegyezik a kifizetés várható értékével.",
"Die Poissonverteilung zählt, wie oft ein Ereignis in einem festen Zeitraum (oder auf einer Seite, Strecke, Fläche) eintritt, wenn die Ereignisse unabhängig und im Mittel gleich häufig auftreten: {0} = λᵏ/k! · e^(−λ). Dabei ist λ die mittlere Anzahl; Erwartungswert und Varianz sind beide λ. Für grosses n und kleines p nähert sie die Binomialverteilung mit λ = n·p an.": "A Poisson-eloszlás azt számolja, hányszor következik be egy esemény rögzített idő alatt (vagy egy oldalon, szakaszon, területen), ha az események függetlenek, és átlagosan egyformán gyakoriak: {0} = λᵏ/k! · e^(−λ). Itt λ az átlagos darabszám; a várható érték és a variancia egyaránt λ. Nagy n és kis p esetén közelíti a λ = n·p paraméterű binomiális eloszlást.",
"Eine Bernoulli-Kette ist ein Versuch mit Treffer (p) und Niete, n-mal unabhängig wiederholt. Die Trefferzahl X ist binomialverteilt: {0} = (n über k)·pᵏ·({1} − p)ⁿ⁻ᵏ. Erwartungswert μ = n·p, Standardabweichung σ = √(n·p·({2} − p)).": "A Bernoulli-kísérletsorozat olyan kísérlet, amelynek kimenetele találat (p) vagy nem találat, és amelyet n-szer egymástól függetlenül megismétlünk. A találatok X száma binomiális eloszlású: {0} = (n alatt k)·pᵏ·({1} − p)ⁿ⁻ᵏ. Várható érték μ = n·p, szórás σ = √(n·p·({2} − p)).",
"Mehrstufige Zufallsexperimente zeichnet man als Baumdiagramm. {0}. Pfadregel: Wahrscheinlichkeiten entlang eines Pfades multiplizieren. {1}. Pfadregel: Wahrscheinlichkeiten aller Pfade eines Ereignisses addieren. Ohne Zurücklegen ändern sich die Wahrscheinlichkeiten von Stufe zu Stufe.": "A többlépcsős véletlen kísérleteket fadiagrammal ábrázoljuk. {0}. útszabály: egy út mentén a valószínűségeket összeszorozzuk. {1}. útszabály: egy esemény összes útjának valószínűségét összeadjuk. Visszatevés nélkül a valószínűségek lépcsőről lépcsőre változnak.",
"Jede Ansicht hat Beispiele; der Rechenweg rechts zeigt Formel und Zwischenschritte mit deinen Zahlen.": "Minden nézethez tartoznak példák; a jobb oldali levezetés a képletet és a részlépéseket a te számaiddal mutatja.",
"Normalverteilung: Grenze ziehen oder die Grenze x, die Anzahl σ bzw. die Prozentzahl eintippen – die anderen beiden rechnen mit. «Art» schaltet zwischen linksseitig, rechtsseitig, zwischen zwei Grenzen und beidseitig um. Die Knöpfe {0}σ, {1}σ, {2}σ und {3} %, {4} %, {5} % setzen die Merkzahlen.": "Normális eloszlás: húzd a határt, vagy írd be az x határt, a σ-k számát, illetve a százalékot – a másik kettő hozzáigazodik. A „Fajta” vált a bal oldali, a jobb oldali, a két határ közötti és a kétoldali eset között. A {0}σ, {1}σ, {2}σ és a {3} %, {4} %, {5} % gombok a megjegyzendő értékeket állítják be.",
"«Grenzwerte»: Mit dem Regler oder «{0} n wachsen lassen» geht die Binomialverteilung in die Poisson- bzw. Normalverteilung über; der Rechenweg enthält die Herleitung der Formel mit den aktuellen Zahlen.": "„Határértékek”: a csúszkával vagy a „{0} n növelése” gombbal a binomiális eloszlás Poisson-, illetve normális eloszlásba megy át; a levezetés a képlet levezetését tartalmazza az aktuális számokkal.",
"Datenanalyse: Eigene Werte tippst du links als Liste ein.": "Adatelemzés: a saját értékeidet bal oldalt listaként írod be.",
"Zahlen links ändern oder Punkte, Grenzen und Balken im Bild ziehen – beides gehört zusammen.": "Változtasd meg a számokat bal oldalt, vagy húzd a pontokat, határokat és oszlopokat az ábrán – a kettő összetartozik.",
