"<0>Faires Spiel:</0> Ein Spiel ist fair, wenn der Einsatz gleich dem Erwartungswert der Auszahlung ist. Dann gewinnt auf lange Sicht niemand.": "<0>Igazságos játék:</0> egy játék akkor igazságos, ha a tét megegyezik a kifizetés várható értékével. Ekkor hosszú távon senki sem nyer.",
